{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Ciwujianoside C3, a triterpenoid saponin with multiple sugar residues, was detected in the cerebral cortex of normal mice after oral administration, directly demonstrating that a structurally related saponin can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Anemoside B4, another triterpenoid saponin, reached a brain Cmax of 187.2 ng/g in rats after oral dosing, providing quantitative evidence of CNS exposure for a saponin.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "A glucose-bearing compound reached 3.1 nmol/g in rat brain, with evidence of GLUT1-mediated transport, supporting transporter-assisted brain entry of glycosides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Hydroxysafflor yellow A, a polar glycoside, reached 1026 ng/g in rat brain, indicating measurable brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Telbivudine, a nucleoside analogue, was bioavailable in mouse CNS at 0.94 µg/g after oral administration, supporting CNS access for polar glycoside-like molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A brominated dihydro-AZT prodrug showed increased brain AUC of 55.7 %ID·min/g in mice, demonstrating that modified nucleoside/glycoside scaffolds can achieve brain exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Pass: multiple structurally related saponins and glycosides are directly detected in brain after systemic administration, indicating meaningful CNS access despite high polarity and large molecular size.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule.",
    "Reported brain concentrations are low (ng/g range), and unbound brain exposure/efflux status is not fully defined.",
    "Some positive detections may involve transporter-mediated uptake or altered BBB conditions rather than passive diffusion."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

